    return p[:-5].replace('/','.')
imports=re.compile(r'^import\s+([A-Za-z0-9_.]+)',re.M)
seen=set(); stack=[]
t=open(root,encoding='utf-8').read()
for m in imports.findall(t):
    if m.startswith('AlgebraicJacobian'): stack.append(m)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=mod2path(m)
    if not os.path.isfile(p): continue
    for m2 in imports.findall(open(p,encoding='utf-8',errors='replace').read()):
        if m2.startswith('AlgebraicJacobian') and m2 not in seen: stack.append(m2)
allmods=set()
for r,ds,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allmods.add(path2mod(os.path.join(r,f)))
unreach=sorted(allmods-seen)
print('total under AlgebraicJacobian/:',len(allmods))
print('reachable transitively:',len(seen & allmods))
print('UNREACHABLE:',len(unreach))
for u in unreach: print('  ',u)
